(window.__quranSurahs=window.__quranSurahs||{})[77]={"nomPhon":"Al-Mursalaat","versets":{"1":{"text":"Par ceux qu'on envoie en rafales,","arabe":"وَٱلْمُرْسَلَٰتِ عُرْفًۭا"},"2":{"text":"et qui soufflent en tempête!","arabe":"فَٱلْعَٰصِفَٰتِ عَصْفًۭا"},"3":{"text":"Et qui dispersent largement [dans toutes les directions].","arabe":"وَٱلنَّٰشِرَٰتِ نَشْرًۭا"},"4":{"text":"Par ceux qui séparent nettement (le bien et le mal),","arabe":"فَٱلْفَٰرِقَٰتِ فَرْقًۭا"},"5":{"text":"et lancent un rappel","arabe":"فَٱلْمُلْقِيَٰتِ ذِكْرًا"},"6":{"text":"en guise d'excuse ou d'avertissement!","arabe":"عُذْرًا أَوْ نُذْرًا"},"7":{"text":"Ce qui vous est promis est inéluctable.","arabe":"إِنَّمَا تُوعَدُونَ لَوَٰقِعٌۭ"},"8":{"text":"Quand donc les étoiles seront effacées,","arabe":"فَإِذَا ٱلنُّجُومُ طُمِسَتْ"},"9":{"text":"et que le ciel sera fendu,","arabe":"وَإِذَا ٱلسَّمَآءُ فُرِجَتْ"},"10":{"text":"et que les montagnes seront pulvérisées,","arabe":"وَإِذَا ٱلْجِبَالُ نُسِفَتْ"},"11":{"text":"et que le moment (pour la réunion) des Messagers a été fixé!...","arabe":"وَإِذَا ٱلرُّسُلُ أُقِّتَتْ"},"12":{"text":"A quel jour tout cela a-t-il été renvoyé?","arabe":"لِأَىِّ يَوْمٍ أُجِّلَتْ"},"13":{"text":"Au Jour de la Décision. [le Jugement]!","arabe":"لِيَوْمِ ٱلْفَصْلِ"},"14":{"text":"Et qui te dira ce qu'est le Jour de la Décision?","arabe":"وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ"},"15":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"16":{"text":"N'avons-nous pas fait périr les premières [générations]?","arabe":"أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ"},"17":{"text":"Puis ne les avons-Nous pas fait suivre par les derniers?","arabe":"ثُمَّ نُتْبِعُهُمُ ٱلْءَاخِرِينَ"},"18":{"text":"C'est ainsi que Nous agissons avec les criminels.","arabe":"كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ"},"19":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"20":{"text":"Ne vous avons-Nous pas créés d'une eau vile","arabe":"أَلَمْ نَخْلُقكُّم مِّن مَّآءٍۢ مَّهِينٍۢ"},"21":{"text":"que Nous avons placée dans un reposoir sûr,","arabe":"فَجَعَلْنَٰهُ فِى قَرَارٍۢ مَّكِينٍ"},"22":{"text":"pour une durée connue?","arabe":"إِلَىٰ قَدَرٍۢ مَّعْلُومٍۢ"},"23":{"text":"Nous l'avons décrété ainsi et Nous décrétons [tout] de façon parfaite.","arabe":"فَقَدَرْنَا فَنِعْمَ ٱلْقَٰدِرُونَ"},"24":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"25":{"text":"N'avons-Nous pas fait de la terre un endroit les contenant tous,","arabe":"أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا"},"26":{"text":"les vivants ainsi que les morts?","arabe":"أَحْيَآءًۭ وَأَمْوَٰتًۭا"},"27":{"text":"Et n'y avons-Nous pas placé fermement de hautes montagnes? Et ne vous avons-Nous pas abreuvés d'eau douce?","arabe":"وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَٰمِخَٰتٍۢ وَأَسْقَيْنَٰكُم مَّآءًۭ فُرَاتًۭا"},"28":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"29":{"text":"Allez vers ce que vous traitiez alors de mensonge!","arabe":"ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ"},"30":{"text":"Allez vers une ombre [fumée de l'Enfer] à trois branches;","arabe":"ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّۢ ذِى ثَلَٰثِ شُعَبٍۢ"},"31":{"text":"qui n'est ni ombreuse ni capable de protéger contre la flamme;","arabe":"لَّا ظَلِيلٍۢ وَلَا يُغْنِى مِنَ ٱللَّهَبِ"},"32":{"text":"car [le feu] jette des étincelles volumineuses comme des châteaux,","arabe":"إِنَّهَا تَرْمِى بِشَرَرٍۢ كَٱلْقَصْرِ"},"33":{"text":"et qu'on prendrait pour des chameaux jaunes.","arabe":"كَأَنَّهُۥ جِمَٰلَتٌۭ صُفْرٌۭ"},"34":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"35":{"text":"Ce sera le jour où ils ne [peuvent] pas parler,","arabe":"هَٰذَا يَوْمُ لَا يَنطِقُونَ"},"36":{"text":"et point ne leur sera donné permission de s'excuser.","arabe":"وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ"},"37":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"38":{"text":"C'est le Jour de la Décision [Jugement], où nous vous réunirons ainsi que les anciens.","arabe":"هَٰذَا يَوْمُ ٱلْفَصْلِ ۖ جَمَعْنَٰكُمْ وَٱلْأَوَّلِينَ"},"39":{"text":"Si vous disposez d'une ruse, rusez donc contre Moi.","arabe":"فَإِن كَانَ لَكُمْ كَيْدٌۭ فَكِيدُونِ"},"40":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"41":{"text":"Les pieux seront parmi des ombrages et des sources","arabe":"إِنَّ ٱلْمُتَّقِينَ فِى ظِلَٰلٍۢ وَعُيُونٍۢ"},"42":{"text":"De même que des fruits selon leurs désirs.","arabe":"وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ"},"43":{"text":"«Mangez et buvez agréablement, pour ce que vous faisiez».","arabe":"كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ"},"44":{"text":"C'est ainsi que Nous récompensons les bienfaisants.","arabe":"إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ"},"45":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"46":{"text":"«Mangez et jouissez un peu (ici-bas); vous êtes certes des criminels».","arabe":"كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ"},"47":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"48":{"text":"Et quand on leur dit: «Inclinez-vous, ils ne s'inclinent pas.","arabe":"وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ"},"49":{"text":"Malheur, ce jour-là, à ceux qui criaient au mensonge.","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"50":{"text":"Après cela, en quelle parole croiront-ils donc?","arabe":"فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ"}}};